//! Assembling Invokr's authentication stack.
//!
//! Every failure here is returned, never panicked, so a misconfiguration
//! surfaces at startup as a message naming the variable rather than as a `401`
//! on the first request that happens to exercise it.

use std::sync::Arc;

use authn_kit::{
    adapters::actix::ActixAuthn,
    claims::{ClaimSource, IdentityClaims},
    mechanisms::{
        ApiTokenAuthenticator, BearerAuthenticator, DisabledAuthenticator, SessionAuthenticator,
    },
    oidc::{CookieSettings, LoginFlow, OidcConfig, OidcProvider},
    AuthnBuilder,
};
use invokr_common::config::{AuthEnv, AuthMode};

use crate::auth::{
    legacy::LegacyApiKeyAuthenticator,
    principal::InvokrProfile,
    routes::AuthRoutesState,
    scope::{InvokrScopes, SESSION_COOKIE},
    session::BrowserSessionAuthenticator,
};

/// Carries the CSRF state and PKCE verifier between `authorize` and the
/// callback. `HttpOnly`, so a script cannot read the verifier.
const PROTECTION_COOKIE: &str = "invokr_protection";

/// The assembled stack: the middleware, plus the state its routes need.
pub struct InvokrAuthn {
    pub middleware: ActixAuthn<InvokrProfile, InvokrScopes>,
    pub routes: AuthRoutesState,
}

/// Builds the authentication stack from configuration.
///
/// `path_prefix` is the API's mount point (`INVOKR_PATH_PREFIX`), used to derive
/// the OIDC callback URL.
pub async fn build(
    auth: &AuthEnv,
    path_prefix: &str,
    dashboard_prefix: &str,
) -> Result<InvokrAuthn, String> {
    let scopes = InvokrScopes::new(path_prefix, dashboard_prefix);
    let builder = AuthnBuilder::<InvokrProfile, _>::new(scopes);

    let (gateway, routes) = match auth.mode {
        AuthMode::Disabled => {
            let gateway = builder
                .with(DisabledAuthenticator::new(development_identity()))
                .build()
                .map_err(|e| e.to_string())?;
            (gateway, AuthRoutesState::disabled(path_prefix))
        }

        AuthMode::Oidc => {
            let oidc = auth
                .oidc
                .as_ref()
                .ok_or("INVOKR_AUTH_MODE=oidc but no OIDC configuration was read")?;

            let redirect_url = format!(
                "{}{}/oidc/login",
                oidc.redirect_host.trim_end_matches('/'),
                path_prefix
            );

            let mut config = OidcConfig::new(
                oidc.issuer_url.clone(),
                oidc.client_id.clone(),
                redirect_url,
            )
            .map_err(|e| e.to_string())?;
            if let Some(secret) = &oidc.client_secret {
                config = config.with_client_secret(secret.clone());
            }

            let provider =
                Arc::new(OidcProvider::discover(config).await.map_err(|e| {
                    format!("OIDC discovery against {} failed: {e}", oidc.issuer_url)
                })?);

            // The API and the dashboard mount under *sibling* prefixes
            // (`INVOKR_PATH_PREFIX` and `INVOKR_DASHBOARD_PATH_PREFIX`), not
            // nested ones. A cookie scoped to either would not be sent to the
            // other, so the user would sign in successfully and land on a
            // dashboard that is immediately signed out. RFC 6265 also requires a
            // matching `Path` to *overwrite* a cookie, so the same mistake
            // breaks logout. Hence `/`.
            let session = CookieSettings::session(SESSION_COOKIE)
                .with_path("/")
                .with_secure(auth.secure_cookies);
            let protection = CookieSettings::protection(PROTECTION_COOKIE)
                .with_path("/")
                .with_secure(auth.secure_cookies);

            let login = Arc::new(
                LoginFlow::new(provider.clone())
                    .with_session_cookie(session)
                    .with_protection_cookie(protection),
            );

            let mut builder = builder;

            // Transitional: accepted only while `INVOKR_API_KEY` is still set.
            if let Some(key) = &auth.legacy_api_key {
                tracing::warn!(
                    "INVOKR_API_KEY is set, so the pre-OIDC shared key is still accepted. \
                     Remove the variable once every caller holds its own credential."
                );
                builder = builder.with(LegacyApiKeyAuthenticator::new(key.clone()));
            }

            if let (Some(prefix), Some(tokens)) = (&auth.api_token_prefix, &auth.static_tokens) {
                let api_tokens =
                    ApiTokenAuthenticator::<InvokrProfile>::from_json(prefix.clone(), tokens)
                        .map_err(|e| format!("INVOKR_API_STATIC_TOKENS is invalid: {e}"))?;
                tracing::info!(
                    "static API tokens enabled: {} token(s) under prefix {:?}",
                    api_tokens.token_count(),
                    api_tokens.prefix()
                );
                builder = builder.with(api_tokens);
            }

            let gateway = builder
                .with(BearerAuthenticator::new(provider.clone()))
                // Last: the only mechanism that turns an *absent* credential
                // into a response rather than declining. Wrapped so the login
                // redirect applies to the dashboard but not to `/v1/*`, where
                // the caller is a program that cannot complete one.
                .with(BrowserSessionAuthenticator::new(
                    SessionAuthenticator::new(provider.clone()).with_login_redirect(login.clone()),
                    path_prefix,
                ))
                .build()
                .map_err(|e| e.to_string())?;

            (gateway, AuthRoutesState::enabled(path_prefix, login))
        }
    };

    tracing::info!(
        "authentication mode {:?}, mechanisms: {:?}",
        auth.mode,
        gateway.authenticator_names()
    );

    // No `with_extensions` hook: the actix adapter already inserts `P::User`
    // into the request extensions, which is exactly what `AuthenticatedRequest`
    // reads. A hook here would insert a second, identical copy.
    let middleware = ActixAuthn::new(gateway);

    Ok(InvokrAuthn { middleware, routes })
}

/// The identity every request resolves to under `INVOKR_AUTH_MODE=disabled`.
///
/// Conspicuously named on purpose: if this ever reaches a real environment it
/// should stand out in an audit log rather than blend in with real users.
fn development_identity() -> IdentityClaims {
    IdentityClaims::new(ClaimSource::StaticToken)
        .with_subject("invokr-auth-disabled")
        .with_preferred_username("invokr-auth-disabled")
        .with_email("invokr-auth-disabled@invalid")
}

//! What an authenticated caller is, and how claims from any mechanism become
//! one.
//!
//! Every mechanism `authn_kit` ships — an OIDC ID token, a JWT access token, a
//! static API token, a machine grant — normalises what it learns into
//! [`IdentityClaims`]. This module holds the single conversion that turns those
//! into Invokr's own principal, so adding a mechanism never adds a second place
//! where "who is this?" is decided.

use authn_kit::{
    claims::{ClaimSource, IdentityClaims},
    AuthProfile,
};

use crate::auth::scope::InvokrScope;

/// An authenticated caller.
///
/// Carries no authority: Invokr has no authorization layer, so every
/// authenticated caller reaches every org and workspace. This type exists to
/// name *who* acted, for audit logs and for the day an authorization layer
/// needs something to key off.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Caller {
    /// A stable, human-readable identity: an email for interactive logins, the
    /// configured principal for a static token.
    pub principal: String,
    /// Which mechanism authenticated this request.
    pub source: ClaimSource,
    /// True for the pre-OIDC shared key, so its use is greppable in logs while
    /// it is being retired.
    pub legacy: bool,
}

impl Caller {
    /// The caller behind the pre-OIDC shared `INVOKR_API_KEY`.
    ///
    /// Deliberately conspicuous: while the key is being decommissioned, every
    /// request still using it should be identifiable in logs so the cutover can
    /// be verified rather than assumed.
    pub fn legacy_api_key() -> Self {
        Self {
            principal: "legacy-api-key".to_string(),
            source: ClaimSource::StaticToken,
            legacy: true,
        }
    }
}

/// Maps claims from any mechanism onto a caller.
///
/// Deliberately permissive about *which* claim carries the identity. Requiring
/// `email` would quietly make Invokr single-provider: some issuers supply only
/// `sub`, and `preferred_username` is a Keycloak convention. `best_effort_username`
/// tries `preferred_username`, `email`, `sub`, then `client_id`.
impl TryFrom<IdentityClaims> for Caller {
    type Error = String;

    fn try_from(claims: IdentityClaims) -> Result<Self, Self::Error> {
        // A machine grant carries no human identity at all — only a validated
        // `client_id` — so it is named after the client rather than rejected
        // for having no email.
        if claims.source == ClaimSource::ClientCredentials {
            let client_id = claims
                .client_id
                .clone()
                .ok_or_else(|| String::from("client_credentials grant carried no client_id"))?;
            return Ok(Self {
                principal: format!("service-account-{client_id}"),
                source: claims.source,
                legacy: false,
            });
        }

        let principal = claims
            .best_effort_username()
            .ok_or_else(|| {
                String::from(
                    "no usable identity claim (looked for preferred_username, email, sub, client_id)",
                )
            })?
            .to_string();

        Ok(Self {
            principal,
            source: claims.source,
            legacy: false,
        })
    }
}

/// Binds the caller and scope types together for `authn_kit`.
pub struct InvokrProfile;

impl AuthProfile for InvokrProfile {
    type User = Caller;
    /// Only distinguishes "needs a credential" from "does not" — Invokr has no
    /// authorization layer, so there is no tenancy realm to model. When one is
    /// added, this scope grows the org/workspace it keys off, and that value
    /// then drives both the credential cache and the policy lookup.
    type Scope = InvokrScope;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn an_id_token_authenticates_as_its_email() {
        let claims = IdentityClaims::new(ClaimSource::IdToken)
            .with_subject("110248495921238986420")
            .with_email("someone@juspay.in");

        let caller = Caller::try_from(claims).expect("id token yields a caller");
        assert_eq!(caller.principal, "someone@juspay.in");
        assert!(!caller.legacy);
    }

    #[test]
    fn preferred_username_wins_over_email() {
        let claims = IdentityClaims::new(ClaimSource::IdToken)
            .with_preferred_username("someone")
            .with_email("someone@juspay.in");

        assert_eq!(Caller::try_from(claims).unwrap().principal, "someone");
    }

    #[test]
    fn an_issuer_supplying_only_a_subject_still_authenticates() {
        // Requiring `email` would quietly make Invokr single-provider: not
        // every issuer supplies one, and `preferred_username` is a Keycloak
        // convention.
        let claims = IdentityClaims::new(ClaimSource::IdToken).with_subject("opaque-subject-id");

        assert_eq!(
            Caller::try_from(claims).unwrap().principal,
            "opaque-subject-id"
        );
    }

    #[test]
    fn a_machine_grant_is_named_after_its_client() {
        // `client_credentials` carries no human identity at all, so demanding
        // an email would reject every machine caller.
        let claims =
            IdentityClaims::new(ClaimSource::ClientCredentials).with_client_id("reporting-svc");

        let caller = Caller::try_from(claims).unwrap();
        assert_eq!(caller.principal, "service-account-reporting-svc");
        assert_eq!(caller.source, ClaimSource::ClientCredentials);
    }

    #[test]
    fn a_machine_grant_without_a_client_id_is_rejected() {
        let claims = IdentityClaims::new(ClaimSource::ClientCredentials);
        assert!(Caller::try_from(claims).is_err());
    }

    #[test]
    fn a_static_token_authenticates_as_its_configured_principal() {
        let claims =
            IdentityClaims::new(ClaimSource::StaticToken).with_preferred_username("aarokya");

        let caller = Caller::try_from(claims).unwrap();
        assert_eq!(caller.principal, "aarokya");
        assert!(!caller.legacy);
    }

    #[test]
    fn claims_carrying_no_identity_at_all_are_rejected() {
        let claims = IdentityClaims::new(ClaimSource::IdToken);
        assert!(Caller::try_from(claims).is_err());
    }

    #[test]
    fn the_legacy_key_is_identifiable_in_logs() {
        // While the shared key is being retired, every request still using it
        // must be greppable, so the cutover can be verified rather than
        // assumed.
        let caller = Caller::legacy_api_key();
        assert!(caller.legacy);
        assert_eq!(caller.principal, "legacy-api-key");
    }
}

//! Invokr's `authn_kit` integration.
//!
//! `authn_kit` deliberately knows nothing about four things, each supplied here:
//!
//! * [`principal`] — what an authenticated caller is, and how claims become one
//! * [`scope`] — whether a route requires a credential at all
//! * [`legacy`] — the pre-OIDC shared key, kept only while callers migrate
//! * [`session`] — confining the login redirect to the dashboard
//! * [`setup`] / [`routes`] — assembling the stack and rendering its endpoints
//!
//! **Authentication only.** Invokr has no authorization layer: once a caller is
//! authenticated it reaches every org and every workspace.

pub mod legacy;
pub mod principal;
pub mod routes;
pub mod scope;
pub mod session;
pub mod setup;

// Only what the binary actually names. The module types (`InvokrProfile`,
// `InvokrScopes`, `AuthRoutesState`, `InvokrAuthn`) stay reachable by path.
pub use principal::Caller;
pub use setup::build;

