//! The pre-OIDC shared API key — a transitional mechanism, not a mode.
//!
//! Before this work, `INVOKR_API_KEY` was the only credential Invokr accepted,
//! and it was rendered into the dashboard's HTML. That leak is closed the moment
//! this ships, because the dashboard is no longer handed a key at all.
//!
//! The key itself lingers only so existing machine callers keep working while
//! they are issued their own tokens. It is registered as one more element of
//! the chain, gated on `INVOKR_API_KEY` still being set — so **removing the
//! variable decommissions it**, with no redeploy and no code change.
//!
//! Delete this file once every environment has dropped the variable.

use async_trait::async_trait;
use authn_kit::{
    authenticator::AuthProfile, AuthContext, AuthError, Authenticator, Credential, Verdict,
};
use secrecy::{ExposeSecret, SecretString};

use crate::auth::principal::{Caller, InvokrProfile};

pub struct LegacyApiKeyAuthenticator {
    key: SecretString,
}

impl LegacyApiKeyAuthenticator {
    pub fn new(key: impl Into<String>) -> Self {
        Self {
            key: SecretString::from(key.into()),
        }
    }
}

impl std::fmt::Debug for LegacyApiKeyAuthenticator {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("LegacyApiKeyAuthenticator { key: <redacted> }")
    }
}

#[async_trait]
impl Authenticator<InvokrProfile> for LegacyApiKeyAuthenticator {
    fn name(&self) -> &'static str {
        "legacy-api-key"
    }

    async fn authenticate(
        &self,
        ctx: &AuthContext<'_, InvokrProfile>,
    ) -> Result<Verdict<<InvokrProfile as AuthProfile>::User>, AuthError> {
        let Credential::Bearer(token) = ctx.credential else {
            return Ok(Verdict::NotApplicable);
        };

        // A mismatch declines rather than fails. The chain is fail-closed — an
        // `Err` from any authenticator ends it immediately — so rejecting here
        // would stop a perfectly good JWT or `ivk_` token from ever being tried,
        // purely because it is not this key.
        if token.expose_secret() != self.key.expose_secret() {
            return Ok(Verdict::NotApplicable);
        }

        Ok(Verdict::Authenticated(Caller::legacy_api_key()))
    }
}

//! Request scoping.
//!
//! Invokr has no authorization layer, so there is no *tenancy* to model here:
//! every authenticated caller reaches every org and workspace. The only
//! distinction this scope draws is whether a route requires a credential at
//! all — infrastructure endpoints and the login callback must not, or the
//! callback would be redirected into the login it is trying to complete.
//!
//! When an authorization layer arrives, this is where an org/workspace realm
//! would be added, and it would then key both the credential cache and any
//! policy lookup.

use std::fmt::Display;

use authn_kit::{AuthRequest, AuthScope, ScopeResolver};

/// The browser session cookie's name.
///
/// **Single source of truth, deliberately.** [`AuthScope::session_cookie_name`]
/// is what `SessionAuthenticator` *reads*, while `CookieSettings::session` is
/// what `LoginFlow` *writes*. If those two ever disagree, login appears to
/// succeed and every subsequent request is anonymous — with no error anywhere.
pub const SESSION_COOKIE: &str = "invokr_session";

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum InvokrScope {
    /// Requires no credential: health, metrics, the OIDC callback, and the
    /// dashboard's static assets, which the browser fetches before any login.
    Public,
    /// Everything else.
    Protected,
}

impl Display for InvokrScope {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Public => f.write_str("public"),
            Self::Protected => f.write_str("protected"),
        }
    }
}

impl AuthScope for InvokrScope {
    fn is_public(&self) -> bool {
        matches!(self, Self::Public)
    }

    /// One cookie for the whole service, on both variants — the name must not
    /// vary with the scope a request happens to resolve to, or a session
    /// established on one route would be invisible on another.
    fn session_cookie_name(&self) -> String {
        SESSION_COOKIE.to_string()
    }
}

/// Decides whether a request needs a credential.
pub struct InvokrScopes {
    path_prefix: String,
    dashboard_prefix: String,
}

impl InvokrScopes {
    pub fn new(path_prefix: impl Into<String>, dashboard_prefix: impl Into<String>) -> Self {
        Self {
            path_prefix: path_prefix.into(),
            dashboard_prefix: dashboard_prefix.into(),
        }
    }

    /// The OIDC callback path, derived from the API prefix — the same
    /// construction `setup::build` uses for the registered redirect URI.
    pub fn callback_path(path_prefix: &str) -> String {
        format!("{path_prefix}/oidc/login")
    }
}

impl ScopeResolver for InvokrScopes {
    type Scope = InvokrScope;

    fn resolve(&self, request: &AuthRequest) -> InvokrScope {
        let path = request.path();
        let api = &self.path_prefix;

        // `/metrics` is mounted *inside* the API prefix (see `router.rs`), so a
        // bare "/metrics" test would never match a prefixed deployment and
        // Prometheus would silently start collecting 401s instead of samples.
        let public = path == format!("{api}/health")
            || path == format!("{api}/metrics")
            || path == InvokrScopes::callback_path(api)
            // Served before the user can possibly be authenticated.
            || path.starts_with(&format!("{}/pkg/", self.dashboard_prefix));

        if public {
            InvokrScope::Public
        } else {
            InvokrScope::Protected
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn request(path: &str) -> AuthRequest {
        AuthRequest::builder().method("GET").path(path).build()
    }

    #[test]
    fn health_and_metrics_are_public_under_a_path_prefix() {
        let scopes = InvokrScopes::new("/invokr", "/dashboard");

        assert!(scopes.resolve(&request("/invokr/health")).is_public());
        // `/metrics` is mounted *inside* the API prefix. Testing a bare
        // "/metrics" would pass against an unprefixed deployment and leave a
        // prefixed one serving 401s to Prometheus, which reports as missing
        // data rather than an error.
        assert!(scopes.resolve(&request("/invokr/metrics")).is_public());
    }

    #[test]
    fn health_and_metrics_are_public_without_a_path_prefix() {
        let scopes = InvokrScopes::new("", "");

        assert!(scopes.resolve(&request("/health")).is_public());
        assert!(scopes.resolve(&request("/metrics")).is_public());
    }

    #[test]
    fn the_oidc_callback_is_public() {
        // If the callback required authentication, the session authenticator
        // would redirect it into the login flow it is trying to complete — an
        // infinite loop that only appears once a real provider is configured.
        let scopes = InvokrScopes::new("/invokr", "/dashboard");
        assert!(scopes.resolve(&request("/invokr/oidc/login")).is_public());
    }

    #[test]
    fn the_callback_path_matches_the_registered_redirect_uri() {
        // `setup::build` derives the redirect URI it registers with the
        // provider from the same prefix. If these two ever diverge, the
        // provider redirects to a path that requires authentication.
        assert_eq!(InvokrScopes::callback_path("/invokr"), "/invokr/oidc/login");
        assert_eq!(InvokrScopes::callback_path(""), "/oidc/login");
    }

    #[test]
    fn dashboard_assets_are_public() {
        // Fetched by the browser before any login can have happened.
        let scopes = InvokrScopes::new("/invokr", "/dashboard");
        assert!(scopes
            .resolve(&request("/dashboard/pkg/invokr_dashboard.js"))
            .is_public());
        assert!(scopes
            .resolve(&request("/dashboard/pkg/invokr_dashboard_bg.wasm"))
            .is_public());
    }

    #[test]
    fn api_and_dashboard_routes_are_protected() {
        let scopes = InvokrScopes::new("/invokr", "/dashboard");

        for path in [
            "/invokr/v1/jobs",
            "/invokr/v1/orgs",
            "/invokr/v1/endpoints",
            "/dashboard/jobs",
            "/dashboard/",
        ] {
            assert_eq!(
                scopes.resolve(&request(path)),
                InvokrScope::Protected,
                "{path} must require a credential"
            );
        }
    }

    #[test]
    fn a_path_merely_containing_health_is_not_public() {
        // Substring matching here would expose any route whose name happens to
        // contain an infrastructure path.
        let scopes = InvokrScopes::new("/invokr", "/dashboard");
        assert_eq!(
            scopes.resolve(&request("/invokr/v1/jobs/health-check")),
            InvokrScope::Protected
        );
        assert_eq!(
            scopes.resolve(&request("/invokr/v1/endpoints/metrics")),
            InvokrScope::Protected
        );
    }

    #[test]
    fn the_session_cookie_name_does_not_vary_by_scope() {
        // `SessionAuthenticator` reads the cookie named by the *scope*, while
        // `LoginFlow` writes the one named in `CookieSettings`. If the name
        // varied per scope, a session established on one route would be
        // invisible on another — login would appear to succeed and every
        // request stay anonymous.
        assert_eq!(InvokrScope::Public.session_cookie_name(), SESSION_COOKIE);
        assert_eq!(InvokrScope::Protected.session_cookie_name(), SESSION_COOKIE);
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::FromRow;

#[derive(Debug, Clone, FromRow)]
pub struct Secret {
    pub name: String,
    pub encrypted_value: Vec<u8>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

#[derive(Debug, Clone, Serialize)]
pub struct SecretResponse {
    pub name: String,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

impl From<Secret> for SecretResponse {
    fn from(s: Secret) -> Self {
        Self {
            name: s.name,
            created_at: s.created_at,
            updated_at: s.updated_at,
        }
    }
}

#[derive(Debug, Deserialize)]
pub struct CreateSecret {
    pub name: String,
    pub value: String,
}

#[derive(Debug, Deserialize)]
pub struct UpdateSecret {
    pub value: String,
}

use crate::extractors::{AuthenticatedRequest, Workspace};
use crate::router::AppState;
use actix_web::{web, HttpResponse};
use invokr_common::{
    crypto, db,
    db::DbContext,
    error::AppError,
    models::secret::{CreateSecret, SecretResponse, UpdateSecret},
    pagination::{encode_cursor, PaginatedResponse, PaginationParams},
};

pub async fn create(
    state: web::Data<AppState>,
    _auth: AuthenticatedRequest,
    ws: Workspace,
    body: web::Json<CreateSecret>,
) -> Result<HttpResponse, AppError> {
    let encrypted = crypto::encrypt(&body.value, &state.config.crypto.encryption_key)
        .map_err(|e| AppError::Internal(format!("Encryption failed: {}", e)))?;

    let prefix = state.prefix();
    let mut conn = invokr_common::db::scoped::scoped_connection(&state.pool, &ws.0.schema_name)
        .await
        .map_err(AppError::from)?;
    let mut db = DbContext::new(&mut conn, prefix);

    let secret = db::secrets::create(&mut db, &body.name, &encrypted)
        .await
        .map_err(|e| match e {
            sqlx::Error::Database(ref db_err) if db_err.constraint().is_some() => {
                AppError::Conflict(format!("Secret '{}' already exists", body.name))
            }
            _ => AppError::from(e),
        })?;

    let resp = SecretResponse::from(secret);
    Ok(HttpResponse::Created().json(serde_json::json!({ "data": {
        "name": resp.name, "created_at": resp.created_at, "updated_at": resp.updated_at,
    }})))
}

pub async fn list(
    state: web::Data<AppState>,
    _auth: AuthenticatedRequest,
    ws: Workspace,
    params: web::Query<PaginationParams>,
) -> Result<HttpResponse, AppError> {
    let prefix = state.prefix();
    let mut conn = invokr_common::db::scoped::scoped_connection(&state.pool, &ws.0.schema_name)
        .await
        .map_err(AppError::from)?;
    let mut db = DbContext::new(&mut conn, prefix);
    let limit = params.effective_limit();
    let cursor = params.decode_cursor();
    let items = db::secrets::list(&mut db, cursor.as_deref(), limit + 1).await?;

    let has_more = items.len() as i64 > limit;
    let items: Vec<_> = items.into_iter().take(limit as usize).collect();
    let next_cursor = if has_more {
        items.last().map(|s| encode_cursor(&s.name))
    } else {
        None
    };

    let data: Vec<serde_json::Value> = items
        .into_iter()
        .map(|s| {
            serde_json::json!({
                "name": s.name, "created_at": s.created_at, "updated_at": s.updated_at,
            })
        })
        .collect();

    Ok(HttpResponse::Ok().json(PaginatedResponse {
        data,
        cursor: next_cursor,
    }))
}

pub async fn get(
    state: web::Data<AppState>,
    _auth: AuthenticatedRequest,
    ws: Workspace,
    path: web::Path<String>,
) -> Result<HttpResponse, AppError> {
    let prefix = state.prefix();
    let mut conn = invokr_common::db::scoped::scoped_connection(&state.pool, &ws.0.schema_name)
        .await
        .map_err(AppError::from)?;
    let mut db = DbContext::new(&mut conn, prefix);
    let name = path.into_inner();
    let secret = db::secrets::get(&mut db, &name)
        .await?
        .ok_or(AppError::SecretNotFound(name))?;

    Ok(HttpResponse::Ok().json(serde_json::json!({ "data": {
        "name": secret.name, "created_at": secret.created_at, "updated_at": secret.updated_at,
    }})))
}

pub async fn update(
    state: web::Data<AppState>,
    _auth: AuthenticatedRequest,
    ws: Workspace,
    path: web::Path<String>,
    body: web::Json<UpdateSecret>,
) -> Result<HttpResponse, AppError> {
    let name = path.into_inner();
    let encrypted = crypto::encrypt(&body.value, &state.config.crypto.encryption_key)
        .map_err(|e| AppError::Internal(format!("Encryption failed: {}", e)))?;

    let prefix = state.prefix();
    let mut conn = invokr_common::db::scoped::scoped_connection(&state.pool, &ws.0.schema_name)
        .await
        .map_err(AppError::from)?;
    let mut db = DbContext::new(&mut conn, prefix);

    let secret = db::secrets::update(&mut db, &name, &encrypted)
        .await?
        .ok_or(AppError::SecretNotFound(name))?;

    Ok(HttpResponse::Ok().json(serde_json::json!({ "data": {
        "name": secret.name, "created_at": secret.created_at, "updated_at": secret.updated_at,
    }})))
}

pub async fn delete(
    state: web::Data<AppState>,
    _auth: AuthenticatedRequest,
    ws: Workspace,
    path: web::Path<String>,
) -> Result<HttpResponse, AppError> {
    let prefix = state.prefix();
    let mut conn = invokr_common::db::scoped::scoped_connection(&state.pool, &ws.0.schema_name)
        .await
        .map_err(AppError::from)?;
    let mut db = DbContext::new(&mut conn, prefix);
    let name = path.into_inner();
    if db::secrets::has_dependent_endpoints(&mut db, &name).await? {
        return Err(AppError::Conflict(format!(
            "Secret '{}' is referenced by endpoints",
            name
        )));
    }
    if !db::secrets::delete(&mut db, &name).await? {
        return Err(AppError::SecretNotFound(name));
    }
    Ok(HttpResponse::NoContent().finish())
}

//! Browser-session authentication, with the login redirect confined to the
//! dashboard.
//!
//! `SessionAuthenticator` turns *any* credential-less `GET` into a redirect
//! into the login flow. That is right for a browser navigating to the dashboard
//! and wrong for an API call: `curl {prefix}/v1/jobs` with a forgotten token
//! would follow the redirect and receive the identity provider's login page
//! with a `200`, which looks like a successful request returning nonsense
//! rather than a missing credential.
//!
//! This wrapper keeps the redirect for the dashboard and converts it to a `401`
//! for `/v1/*`, where the caller is a program.

use async_trait::async_trait;
use authn_kit::{
    authenticator::AuthProfile, mechanisms::SessionAuthenticator, AuthContext, AuthError,
    Authenticator, Verdict,
};

use crate::auth::principal::InvokrProfile;

pub struct BrowserSessionAuthenticator {
    inner: SessionAuthenticator<InvokrProfile>,
    /// Requests under `{api_prefix}/v1/` are programs, not browsers.
    api_prefix: String,
}

impl BrowserSessionAuthenticator {
    pub fn new(inner: SessionAuthenticator<InvokrProfile>, api_prefix: impl Into<String>) -> Self {
        Self {
            inner,
            api_prefix: api_prefix.into(),
        }
    }

    fn is_api_call(&self, path: &str) -> bool {
        is_api_call(&self.api_prefix, path)
    }
}

/// Whether `path` is a programmatic API call rather than a browser navigation.
///
/// Free-standing so it is testable without an [`OidcProvider`], which would
/// otherwise require a live identity provider to construct.
///
/// [`OidcProvider`]: authn_kit::oidc::OidcProvider
fn is_api_call(api_prefix: &str, path: &str) -> bool {
    path.starts_with(&format!("{api_prefix}/v1/"))
}

#[async_trait]
impl Authenticator<InvokrProfile> for BrowserSessionAuthenticator {
    fn name(&self) -> &'static str {
        "browser-session"
    }

    async fn authenticate(
        &self,
        ctx: &AuthContext<'_, InvokrProfile>,
    ) -> Result<Verdict<<InvokrProfile as AuthProfile>::User>, AuthError> {
        match self.inner.authenticate(ctx).await {
            // An API caller gets told what is wrong, rather than being sent on a
            // round trip to a login page it cannot complete.
            Err(AuthError::Redirect { .. }) if self.is_api_call(ctx.request.path()) => {
                Err(AuthError::unauthenticated(
                    "no credential presented; send an API token or a session cookie",
                ))
            }
            other => other,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::is_api_call;

    #[test]
    fn versioned_api_paths_are_api_calls() {
        assert!(is_api_call("/invokr", "/invokr/v1/jobs"));
        assert!(is_api_call("", "/v1/orgs"));
    }

    #[test]
    fn dashboard_paths_are_not() {
        // These must keep the login redirect: a person typing the URL should
        // land on the identity provider, not read a 401.
        assert!(!is_api_call("/invokr", "/dashboard/jobs"));
        assert!(!is_api_call("", "/"));
        assert!(!is_api_call("", "/dashboard/"));
    }

    #[test]
    fn a_lookalike_prefix_is_not_an_api_call() {
        // `/invokr-staging/v1/...` must not be mistaken for this deployment's
        // API just because the prefix is a string prefix of it.
        assert!(!is_api_call("/invokr", "/invokr-staging/v1/jobs"));
    }
}

//! The OIDC callback and logout routes.
//!
//! `LoginFlow` returns *data* — a location and a list of cookie directives —
//! and this module is the only place that turns those into an actix response.
//! The protocol logic stays testable without a web framework.

use std::sync::Arc;

use actix_web::{cookie::Cookie, web, HttpRequest, HttpResponse};
use authn_kit::{
    oidc::{CallbackParams, LoginFlow},
    AuthError,
};

use crate::auth::scope::SESSION_COOKIE;

/// What the auth routes need at request time.
#[derive(Clone)]
pub struct AuthRoutesState {
    /// `None` under `INVOKR_AUTH_MODE=disabled` — there is nothing to log in to.
    pub login: Option<Arc<LoginFlow>>,
    pub path_prefix: String,
}

impl AuthRoutesState {
    pub fn disabled(path_prefix: &str) -> Self {
        Self {
            login: None,
            path_prefix: path_prefix.to_string(),
        }
    }

    pub fn enabled(path_prefix: &str, login: Arc<LoginFlow>) -> Self {
        Self {
            login: Some(login),
            path_prefix: path_prefix.to_string(),
        }
    }
}

/// `GET {prefix}/oidc/login` — the provider's callback.
///
/// Registered at exactly the redirect URI `setup::build` derives, and treated as
/// a public scope: authenticating it would redirect the callback into the login
/// it is completing.
async fn callback(
    request: HttpRequest,
    state: web::Data<AuthRoutesState>,
) -> Result<HttpResponse, actix_web::Error> {
    let Some(login) = &state.login else {
        return Ok(HttpResponse::NotFound().json(serde_json::json!({
            "error": {
                "code": "AUTH_DISABLED",
                "message": "Authentication is disabled; there is no login flow"
            }
        })));
    };

    let params = CallbackParams::from_query(request.query_string())
        .map_err(|e| actix_web::error::InternalError::from_response("", render(&e)))?;

    let protection = request
        .cookie(&login.protection_cookie().name)
        .map(|c| c.value().to_string());

    let complete = login
        .complete(params, protection.as_deref())
        .await
        .map_err(|e| actix_web::error::InternalError::from_response("", render(&e)))?;

    let mut response = HttpResponse::Found();
    response.insert_header(("Location", complete.redirect_to.clone()));
    for directive in &complete.cookies {
        response.cookie(Cookie::from(directive));
    }
    Ok(response.finish())
}

/// `GET {prefix}/logout` — clears the session and returns to the root.
async fn logout(state: web::Data<AuthRoutesState>) -> HttpResponse {
    let mut response = HttpResponse::Found();
    response.insert_header(("Location", format!("{}/", state.path_prefix)));

    if let Some(login) = &state.login {
        response.cookie(Cookie::from(&login.session_cookie().clear()));
    } else {
        // Best effort when no flow exists: clear by name and path.
        let mut cookie = Cookie::new(SESSION_COOKIE, "");
        cookie.set_path("/");
        cookie.make_removal();
        response.cookie(cookie);
    }

    response.finish()
}

fn render(error: &AuthError) -> HttpResponse {
    authn_kit::adapters::actix::error_to_response(error)
}

/// Registers the auth routes at their absolute paths.
///
/// Deliberately **not** a `web::scope`. With no `INVOKR_PATH_PREFIX` the scope
/// path is `""`, and an empty actix scope matches every request — it would
/// shadow the entire API and dashboard, which answer `404` from inside it.
/// Registering absolute routes has no such failure mode at either setting.
pub fn configure(path_prefix: &str) -> impl FnOnce(&mut web::ServiceConfig) + 'static {
    let login = format!("{path_prefix}/oidc/login");
    let logout_path = format!("{path_prefix}/logout");

    move |cfg: &mut web::ServiceConfig| {
        cfg.route(&login, web::get().to(callback));
        cfg.route(&logout_path, web::get().to(logout));
    }
}

