  {{- with .Values.api.ingress.className }}
  ingressClassName: {{ . }}
  {{- end }}
  {{- with .Values.api.ingress.tls }}
  tls:
    {{- toYaml . | nindent 4 }}
  {{- end }}
  rules:
    {{- range .Values.api.ingress.hosts }}
    - host: {{ .host | quote }}
      http:
        paths:
          {{- if .paths }}
          {{- range .paths }}
          - path: {{ .path }}
            pathType: {{ .pathType }}
            backend:
              service:
                name: {{ include "invokr.fullname" $ }}-api
                port:
                  number: {{ $.Values.api.service.port }}
          {{- end }}
          {{- else }}
          - path: {{ $pathPrefix | default "/" }}
            pathType: Prefix
            backend:
              service:
                name: {{ include "invokr.fullname" $ }}-api
                port:
                  number: {{ $.Values.api.service.port }}
          {{- if and $.Values.dashboard.enabled $pathPrefix $.Values.dashboard.pathPrefix }}
          - path: {{ $.Values.dashboard.pathPrefix }}
            pathType: Prefix
            backend:
              service:
                name: {{ include "invokr.fullname" $ }}-api
                port:
                  number: {{ $.Values.api.service.port }}
          {{- end }}
          {{- end }}
    {{- end }}
{{- end }}

